import{_ as a,o,c as i,a2 as n}from"./chunks/framework.CgxQ0r6v.js";const p=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 1","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Redes/documentacion/II-IV/Lectura_Catedra_Evaluacion_1.md","filePath":"materias/Redes/documentacion/II-IV/Lectura_Catedra_Evaluacion_1.md"}'),r={name:"materias/Redes/documentacion/II-IV/Lectura_Catedra_Evaluacion_1.md"};function s(t,e,l,c,d,u){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="manual-de-estudio-profundo-evaluacion-1" tabindex="-1">Manual de Estudio Profundo: Evaluación 1 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-1" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 1&quot;">​</a></h1><h2 id="materia-redes-trayecto-ii" tabindex="-1">Materia: Redes (Trayecto II) <a class="header-anchor" href="#materia-redes-trayecto-ii" aria-label="Permalink to &quot;Materia: Redes (Trayecto II)&quot;">​</a></h2><h3 id="eje-tematico-fundamentos-y-medios-de-comunicacion" tabindex="-1">Eje Temático: Fundamentos y Medios de Comunicación <a class="header-anchor" href="#eje-tematico-fundamentos-y-medios-de-comunicacion" aria-label="Permalink to &quot;Eje Temático: Fundamentos y Medios de Comunicación&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-conquista-de-la-distancia" tabindex="-1">🧭 Introducción: La Conquista de la Distancia <a class="header-anchor" href="#🧭-introduccion-la-conquista-de-la-distancia" aria-label="Permalink to &quot;🧭 Introducción: La Conquista de la Distancia&quot;">​</a></h2><p>A lo largo de los trimestres pasados, hemos estudiado cómo las computadoras procesan información internamente (Algoritmia) y cómo podemos construir sistemas complejos (Programación II). Pero, ¿de qué sirve una computadora hiper-potente si está aislada del mundo?</p><p>La materia de <strong>Redes</strong> es el estudio de la infraestructura que conecta a la humanidad. Es la ciencia de convertir la información (documentos, imágenes, videos) en señales eléctricas, ópticas o electromagnéticas, enviarlas al otro lado del mundo en fracciones de segundo y reconstruirlas perfectamente.</p><hr><h2 id="🏛️-capitulo-i-el-sistema-de-comunicacion-basico" tabindex="-1">🏛️ CAPÍTULO I: El Sistema de Comunicación Básico <a class="header-anchor" href="#🏛️-capitulo-i-el-sistema-de-comunicacion-basico" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: El Sistema de Comunicación Básico&quot;">​</a></h2><p>Toda red de computadoras, por más compleja que sea (incluso el Internet global), se reduce a un modelo de comunicación teórico universal propuesto por Claude Shannon en 1948.</p><p>Este modelo exige cuatro componentes innegociables:</p><ol><li><strong>Emisor (Fuente):</strong> El dispositivo que origina el mensaje y lo codifica (ej. Tu computadora).</li><li><strong>Mensaje:</strong> La información pura que se desea transmitir (ej. Un correo electrónico).</li><li><strong>Medio (Canal):</strong> La autopista física por donde viaja la señal. Puede ser tangible (un cable) o intangible (el aire).</li><li><strong>Receptor (Destino):</strong> El dispositivo que recibe la señal, la decodifica y recupera el mensaje original.</li></ol><p>Si el Medio falla, no hay red. Si el Emisor y el Receptor no hablan el mismo &quot;idioma&quot; (Protocolo), el mensaje llega pero es incomprensible.</p><hr><h2 id="🧩-capitulo-ii-medios-fisicos-de-transmision" tabindex="-1">🧩 CAPÍTULO II: Medios Físicos de Transmisión <a class="header-anchor" href="#🧩-capitulo-ii-medios-fisicos-de-transmision" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Medios Físicos de Transmisión&quot;">​</a></h2><p>Los datos dentro de tu PC son ceros y unos lógicos. Para viajar por el mundo físico, deben transformarse en un fenómeno físico. Los clasificamos en dos grandes familias:</p><h3 id="_2-1-medios-guiados-alambricos" tabindex="-1">2.1 Medios Guiados (Alámbricos) <a class="header-anchor" href="#_2-1-medios-guiados-alambricos" aria-label="Permalink to &quot;2.1 Medios Guiados (Alámbricos)&quot;">​</a></h3><p>El canal físico está delimitado y contiene la señal para que no escape.</p><ul><li><strong>Cable Coaxial:</strong> Usado históricamente en televisión por cable y primeras redes. Tiene un núcleo de cobre grueso blindado contra interferencias.</li><li><strong>Par Trenzado (Cobre):</strong> El rey indiscutible de las redes locales (LAN). Consiste en pares de hilos de cobre entrelazados entre sí. ¿Por qué se trenzan? Por física electromagnética: el trenzado cancela el ruido y la interferencia (Diafonía) generada por los cables adyacentes. Se divide en UTP (Sin blindaje, barato, el más común) y STP (Con blindaje de aluminio, para entornos industriales ruidosos).</li><li><strong>Fibra Óptica:</strong> El pináculo de la velocidad. No usa electricidad, usa <strong>Luz</strong> rebotando dentro de un hilo de vidrio o plástico extremadamente fino. Es inmune a la interferencia electromagnética (no le afectan las tormentas eléctricas ni motores cercanos) y puede transmitir terabytes de datos a distancias intercontinentales cruzando los océanos.</li></ul><h3 id="_2-2-medios-no-guiados-inalambricos" tabindex="-1">2.2 Medios No Guiados (Inalámbricos) <a class="header-anchor" href="#_2-2-medios-no-guiados-inalambricos" aria-label="Permalink to &quot;2.2 Medios No Guiados (Inalámbricos)&quot;">​</a></h3><p>Usan el aire o el vacío del espacio como medio, transmitiendo a través de ondas electromagnéticas.</p><ul><li><strong>Microondas / Wi-Fi (Estándar 802.11):</strong> Radiación de alta frecuencia. Excelente para movilidad local, pero susceptible a interferencias físicas (paredes gruesas) y otras señales (como el microondas de tu cocina).</li><li><strong>Satélites y Ondas de Radio:</strong> Para cobertura global.</li></ul><hr><h2 id="🏗️-capitulo-iii-el-arte-del-cableado-normativas-eia-tia-568" tabindex="-1">🏗️ CAPÍTULO III: El Arte del Cableado (Normativas EIA/TIA 568) <a class="header-anchor" href="#🏗️-capitulo-iii-el-arte-del-cableado-normativas-eia-tia-568" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: El Arte del Cableado (Normativas EIA/TIA 568)&quot;">​</a></h2><p>En el mundo profesional de las Redes LAN, no podemos simplemente conectar cables de colores al azar en los conectores (RJ45). La industria ha establecido estándares mundiales de colores para garantizar que un ingeniero en Venezuela y uno en Japón entiendan la misma red.</p><p>Existen dos normas principales de orden de colores para los 8 hilos internos del cable UTP:</p><ul><li><strong>Norma T568A:</strong> Blanco/Verde, Verde, Blanco/Naranja, Azul, Blanco/Azul, Naranja, Blanco/Marrón, Marrón.</li><li><strong>Norma T568B:</strong> Blanco/Naranja, Naranja, Blanco/Verde, Azul, Blanco/Azul, Verde, Blanco/Marrón, Marrón.</li></ul><h3 id="_3-1-tipos-de-cables-segun-su-uso" tabindex="-1">3.1 Tipos de Cables según su Uso <a class="header-anchor" href="#_3-1-tipos-de-cables-segun-su-uso" aria-label="Permalink to &quot;3.1 Tipos de Cables según su Uso&quot;">​</a></h3><ol><li><strong>Cable Directo (Straight-Through):</strong> Usa la misma norma en ambos extremos (A-A o B-B). <em>Uso:</em> Conectar equipos de diferente capa lógica (ej. PC a Switch, o Router a Switch).</li><li><strong>Cable Cruzado (Crossover):</strong> Usa la norma A en un extremo y la B en el otro. <em>Uso:</em> Conectar equipos de la misma capa lógica directamente (ej. PC a PC, o Switch a Switch antiguos). <em>(Nota: Hoy en día las tarjetas de red modernas tienen Auto-MDIX, un sistema inteligente que cruza internamente la señal si te equivocas de cable, pero el conocimiento del estándar cruzado sigue siendo evaluado teóricamente).</em></li></ol><hr><h2 id="💻-laboratorio-teorico-ponchado-de-cable-crimping" tabindex="-1">💻 Laboratorio Teórico: Ponchado de Cable (Crimping) <a class="header-anchor" href="#💻-laboratorio-teorico-ponchado-de-cable-crimping" aria-label="Permalink to &quot;💻 Laboratorio Teórico: Ponchado de Cable (Crimping)&quot;">​</a></h2><p>En el entorno real de un ingeniero, crear un &quot;Patch Cord&quot; (cable de red a medida) requiere destreza física:</p><ol><li><strong>Herramientas:</strong> Cable UTP Cat 5e/6, Conectores RJ45, Ponchadora (Crimping tool), Pelacables.</li><li><strong>Preparación:</strong> Pelar 3 centímetros de la cubierta externa plástica (Chaqueta) con cuidado de no cortar los hilos internos de cobre.</li><li><strong>Ordenamiento:</strong> Destrenzar los 4 pares, aplanarlos y ordenarlos estrictamente según la norma T568B (la más usada mundialmente).</li><li><strong>Corte y Ponchado:</strong> Cortar las puntas para que queden perfectamente rectas e introducirlas en el conector RJ45 (los pines dorados viendo hacia ti). Apretar fuerte con la ponchadora hasta escuchar el &quot;clic&quot; metálico que perfora el cable y hace contacto eléctrico.</li></ol><hr><h2 id="📘-anexo-diccionario-tecnico-formal" tabindex="-1">📘 ANEXO: Diccionario Técnico Formal <a class="header-anchor" href="#📘-anexo-diccionario-tecnico-formal" aria-label="Permalink to &quot;📘 ANEXO: Diccionario Técnico Formal&quot;">​</a></h2><ul><li><strong>Telecomunicaciones:</strong> Disciplina tecnológica enfocada en la transmisión, emisión y recepción de signos, señales, o información de cualquier naturaleza a través de medios electromagnéticos, ópticos o físicos.</li><li><strong>Medio de Transmisión Guiado:</strong> Soporte físico tangible (cobre, fibra de vidrio) utilizado para contener, confinar y dirigir ondas electromagnéticas o luminosas desde un emisor hasta un receptor.</li><li><strong>Par Trenzado (Twisted Pair):</strong> Cable compuesto por pares de conductores de cobre aislados y entrelazados en espiral, diseño geométrico destinado a minimizar la interferencia electromagnética (EMI) y la diafonía (crosstalk).</li><li><strong>UTP (Unshielded Twisted Pair):</strong> Variante de cable de par trenzado carente de blindaje metálico adicional, siendo el estándar de facto para la topología de cableado estructurado en infraestructuras LAN por su bajo costo y flexibilidad.</li><li><strong>Fibra Óptica:</strong> Filamento dieléctrico conductor de energía luminosa, caracterizado por su inmunidad total a interferencias electromagnéticas, nula emisión térmica y capacidades de ancho de banda superlativas.</li><li><strong>RJ45 (Registered Jack 45):</strong> Interfaz física y estándar de conectorización modular de 8 posiciones y 8 contactos (8P8C) empleada universalmente en la terminación de cables de red Ethernet de cobre.</li><li><strong>Normas T568A / T568B:</strong> Estándares técnicos de terminación estipulados por la TIA/EIA que especifican el esquema estricto de asignación de pines (pinout) y código de colores para cables UTP en conectores modulares de 8 pines.</li></ul>',36)])])}const g=a(r,[["render",s]]);export{p as __pageData,g as default};
